        c_small = [0.5151, 1.5204, 2.5253, 3.5301, 4.5345, 5.5389]
        c_big = [0.5523, 1.6113, 2.6569, 3.6928, 4.7214, 5.7444]
        beam_y = 2.55
        clock = ValueTracker(0.0)

        def pendulum(x, rod_len, times, angles, radius, color):
            pivot = np.array([x, beam_y, 0.0])

            def bob_point():
                th = float(np.interp(clock.get_value(), times, angles))
                return pivot + rod_len * np.array([np.sin(th), -np.cos(th), 0.0])

            rod = always_redraw(lambda: Line(pivot, bob_point(), color=GREY_A, stroke_width=3))
            bob = always_redraw(lambda: Dot(bob_point(), radius=radius, color=color))
            trail = TracedPath(bob_point, stroke_color=color, stroke_width=2, dissipating_time=0.7)
            # The trail gains points every frame, so it is added after any fade-in
            # (a fading mobject's family must not change mid-animation).
            return VGroup(rod, bob), trail

        def counter(x, crossings, color):
            # completed swings = zero crossings passed, two per swing
            return always_redraw(lambda: Text(
                "swings: " + str(int(np.searchsorted(crossings, clock.get_value())) // 2),
                font_size=24, color=color).move_to([x, -3.0, 0]))

        title = Text("The pendulum race", font_size=34, color=YELLOW).to_edge(UP, buff=0.25)
        beam = Line([-6.3, beam_y, 0], [6.3, beam_y, 0], color=GREY_B, stroke_width=6)

        # Race 1: mass vs length
        p_a, tr_a = pendulum(-4.4, 1.9, t1, th_short, 0.13, BLUE)
        p_b, tr_b = pendulum(-1.3, 1.9, t1, th_short, 0.26, TEAL)
        p_c, tr_c = pendulum(3.3, 3.8, t1, th_long, 0.13, ORANGE)
        tags = VGroup(
            Text("1 kg", font_size=26, color=BLUE).move_to([-4.4, -2.45, 0]),
            Text("3 kg", font_size=26, color=TEAL).move_to([-1.3, -2.45, 0]),
            Text("1 kg, string x2", font_size=26, color=ORANGE).move_to([3.3, -2.45, 0]),
        )
        counters = VGroup(counter(-4.4, c_short, BLUE), counter(-1.3, c_short, TEAL),
                          counter(3.3, c_long, ORANGE))
        self.play(FadeIn(title), Create(beam), run_time=0.8)
        self.play(FadeIn(p_a), FadeIn(p_b), FadeIn(p_c), FadeIn(tags), run_time=0.8)
        self.add(tr_a, tr_b, tr_c, counters)
        self.play(clock.animate.set_value(7.0), run_time=7.0, rate_func=linear)
        verdict1 = Text('Equal strings: perfect step, mass or not.   Double length: 1.41× slower', font_size=24, color=YELLOW_A).to_edge(DOWN, buff=0.12)
        self.play(FadeIn(verdict1, shift=0.2 * UP), run_time=0.7)
        self.wait(1.2)

        # Race 2: small vs wide release, same string
        race1 = VGroup(p_a, p_b, p_c, tr_a, tr_b, tr_c, tags, counters, verdict1)
        for m in race1.get_family():
            m.clear_updaters()
        self.play(FadeOut(race1), run_time=0.6)
        clock.set_value(0.0)
        p_small, tr_small = pendulum(-2.7, 1.9, t2, th_small, 0.16, BLUE)
        p_big, tr_big = pendulum(2.7, 1.9, t2, th_big, 0.16, RED)
        tags2 = VGroup(
            Text("released from 10°", font_size=26, color=BLUE).move_to([-2.7, -2.45, 0]),
            Text("released from 60°", font_size=26, color=RED).move_to([2.7, -2.45, 0]),
        )
        counters2 = VGroup(counter(-2.7, c_small, BLUE), counter(2.7, c_big, RED))
        self.play(FadeIn(p_small), FadeIn(p_big), FadeIn(tags2), run_time=0.8)
        self.add(tr_small, tr_big, counters2)
        self.play(clock.animate.set_value(6.5), run_time=6.5, rate_func=linear)
